import * as THREE from './three.module.js';
import {bodyScale} from './roster.js';
export function characterLook(p,c){const scale=bodyScale(c);p.g.scale.set(scale.width,scale.height,scale.width);p.skin.color.set(c.skin);p.hair.material.color.set(c.hair);p.bands.material.color.set(c.band);p.bands.wristMaterial.color.set(c.wrist);p.body.traverse(o=>{if(o.userData.headband)o.visible=!c.hat;});
 if(!p.cap){const cap=new THREE.Group(),cloth=new THREE.MeshStandardMaterial({color:c.hatColor,roughness:.95});const crown=new THREE.Mesh(new THREE.SphereGeometry(.15,24,16,0,Math.PI*2,0,Math.PI*.48),cloth);crown.position.y=1.675;crown.scale.z=1.05;const bill=new THREE.Mesh(new THREE.SphereGeometry(.14,24,12),cloth);bill.position.set(0,1.675,.145);bill.scale.set(1.1,.065,1.0);cap.add(crown,bill);cap.traverse(o=>{if(o.isMesh)o.castShadow=true;});p.body.add(cap);p.cap=cap;p.capMaterial=cloth;}p.cap.visible=c.hat;p.capMaterial.color.set(c.hatColor);p.character=c;}
